def main():
    if not os.path.exists(os.path.join(ROOT, "daily_run.py")):
        print("ERROR: daily_run.py is not in this folder. Save the patch in "
              "the gallery repo's root folder. NOTHING was written.")
        return 1
    dr = open(os.path.join(ROOT, "daily_run.py"), "rb").read()
    if b"horizons_check.py" in dr:
        print("ERROR: daily_run.py already runs horizons_check.py; this "
              "patch has run. NOTHING was written.")
        return 1
    failures, notes, staged = [], [], {}
    for path, text in NEW_FILES.items():
        full = os.path.join(ROOT, *path.split("/"))
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n")
            if have != text.encode("ascii"):
                failures.append("EXISTS %s already exists with other "
                                "content" % path)
            else:
                print("ok  %-44s already present, identical" % path)
            continue
        staged[path] = text.encode("ascii")
        print("ok  %-44s new, %d bytes" % (path, len(staged[path])))
    current = {}
    for path, label, old, new in EDITS:
        if path not in current:
            raw = open(os.path.join(ROOT, *path.split("/")), "rb").read()
            if b"\r\n" in raw:
                notes.append("note: %s was CRLF in the working copy; "
                             "written LF" % path)
            current[path] = raw.replace(b"\r\n", b"\n")
        o, n = old.encode("ascii"), new.encode("ascii")
        count = current[path].count(o)
        if count != 1:
            failures.append("ANCHOR FAIL %s -- %s: expected 1 match, found "
                            "%d" % (path, label, count))
            continue
        current[path] = current[path].replace(o, n)
        print("ok  %-44s %s" % (path, label))
    if failures:
        for f in failures:
            print(f)
        print("FAILURE: NOTHING was written. Undo is not needed.")
        return 1
    for path, data in list(staged.items()) + list(current.items()):
        full = os.path.join(ROOT, *path.split("/"))
        os.makedirs(os.path.dirname(full), exist_ok=True)
        with open(full, "wb") as handle:
            handle.write(data)
    for n in notes:
        print(n)
    print("patch applied: %d new file(s), %d edit(s) in %d file(s)."
          % (len(staged), len(EDITS), len(current)))
    print("")
    print("NEXT, in this order:")
    print(" 1. Run gallery_maintenance_run.py (offline). It pulls the "
          "orrery's new export and writes Halley's and Encke's names, words "
          "and links. Expect two red rows, both correct for now: 'Horizons "
          "confirmations' (nothing confirmed yet) and 'Cache in step' (the "
          "cache still says 1P/Halley and 2P/Encke).")
    print(" 2. Run the Daily Run. Its step 2 is the Horizons check's first "
          "live run: expect PASS, 13 entries agreeing, and both pins the "
          "newest. Its cache build and offline run should then be all "
          "green.")
    print(" 3. Commit and push, then the live maintenance run.")
    print(" 4. Move this script into documentation/.")
    print("Undo is Discard Changes in GitHub Desktop.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
